#define KERNEL_HELPERS_ONLY
#include "kernel.cpp"
Mesh neck(){Mesh mesh;std::vector<Vec3>points;for(auto section:{std::pair<float,float>{-2,1},{0,1},{.25f,.15f},{1,.15f}}){float z=section.first,r=section.second;for(auto p:{Vec3{-r,-r,z},Vec3{r,-r,z},Vec3{r,r,z},Vec3{-r,r,z}})points.push_back(p);}auto triangle=[&](int a,int b,int c){Triangle t{v(points[a]),v(points[b]),v(points[c])};auto n=storm_ship_hull::normalized(storm_ship_hull::cross(t[1].position-t[0].position,t[2].position-t[0].position));for(auto&x:t)x.normal=n;mesh[0].push_back(t);};for(int ring=0;ring<3;++ring)for(int side=0;side<4;++side){int a=ring*4+side,b=ring*4+(side+1)%4,c=b+4,d=a+4;triangle(a,b,c);triangle(a,c,d);}triangle(0,3,2);triangle(0,2,1);triangle(12,13,14);triangle(12,14,15);return mesh;}
int main(){auto mesh=neck();auto gun=box(.1f);for(auto&t:gun[0])for(auto&v:t)v.position.x+=4;mesh[9]=gun[0];std::cout<<"original volume="<<closedVolume(mesh)<<std::endl;assert(closedVolume(mesh)>0);Surface original{mesh,{},{}};Plane full{{-1,0,0},0};for(float y:{-.15f,-.05f,.05f,.15f}){BeamSample sample;sample.start={.16f,y,.6f};sample.direction={-1,0,0};sample.radius=.13;sample.depth=.4f;full.beams.push_back(sample);}auto partial=full;for(auto&b:partial.beams)b.depth=.05f;auto notched=splitSurface(original,partial,{});assert(notched.complete);auto none=detachEnclosed(original,notched.kept);assert(none.empty());auto cut=splitSurface(original,full,{});assert(cut.complete);auto diagnostic=canonicalMesh(cut.kept);std::ofstream out(".local-archives/metal-renderer-evidence/ship-cut-topology-20261016/bow-kept-triangles.txt");for(auto&o:diagnostic)for(auto&t:o.second){out<<o.first;for(auto&v:t)out<<" "<<std::setprecision(10)<<v.position.x<<" "<<v.position.y<<" "<<v.position.z;out<<"\n";}out.close();auto pieces=detachEnclosed(original,cut.kept);std::cout<<"pieces="<<pieces.size()<<" body="<<closedCutVolume(canonicalMesh(cut.kept))<<std::endl;assert(pieces.size()==1);assert(bounds(pieces[0].outer).hi.z==1);assert(bounds(pieces[0].outer).lo.z>.4);assert(!pieces[0].outer.count(9));assert(cut.kept.outer.at(9).size()==gun[0].size());assert(std::memcmp(cut.kept.outer.at(9).data(),gun[0].data(),gun[0].size()*sizeof(Triangle))==0);assert(closedCutVolume(canonicalMesh(pieces[0]))>0);std::cout<<"completed finite bow sever / partial notch / untouched authored gun PASS\n";}
